/**
 * Filter helpers for tests
 */
export function getExactDuplicatePairs(): DedupFixturePair[] {
  return DEDUP_FIXTURE_PAIRS.filter((p) => p.tier === 'EXACT_DUPLICATE');
}

export function getSuspectedDuplicatePairs(): DedupFixturePair[] {
  return DEDUP_FIXTURE_PAIRS.filter((p) => p.tier === 'SUSPECTED_DUPLICATE');
}

export function getDivergentPairs(): DedupFixturePair[] {
  return DEDUP_FIXTURE_PAIRS.filter((p) => p.tier === 'DIVERGENT');
}
